"""Mock dataset and data layer for the book API. No HTTP knowledge here."""

import copy

BOOKS = [
    {"id": 1, "title": "Pride and Prejudice", "author_id": 1,
     "author": "Jane Austen", "year": 1813},
    {"id": 2, "title": "Emma", "author_id": 1,
     "author": "Jane Austen", "year": 1815},
    {"id": 3, "title": "Nineteen Eighty-Four", "author_id": 2,
     "author": "George Orwell", "year": 1949},
    {"id": 4, "title": "Animal Farm", "author_id": 2,
     "author": "George Orwell", "year": 1945},
    {"id": 5, "title": "Cien a\u00f1os de soledad", "author_id": 3,
     "author": "Gabriel Garc\u00eda M\u00e1rquez", "year": 1967},
]


class BookStore:
    """In-memory book store. All returned objects are deep copies."""

    def __init__(self, books=None):
        self._books = copy.deepcopy(books if books is not None else BOOKS)

    def list_books(self):
        """Return deep copies of all books, in dataset order."""
        return copy.deepcopy(self._books)

    def get_book(self, book_id):
        """Return a deep copy of the book with the given id, or None."""
        for book in self._books:
            if book["id"] == book_id:
                return copy.deepcopy(book)
        return None

    def books_by_author(self, author_id):
        """Return deep copies of books with the given author_id ([] if none)."""
        return [copy.deepcopy(b) for b in self._books
                if b["author_id"] == author_id]

import unittest
from collections import Counter

from bookapi import BOOKS as PKG_BOOKS, BookStore as PkgBookStore
from bookapi.data import BOOKS, BookStore

EXPECTED_KEYS = {"id", "title", "author_id", "author", "year"}
EXPECTED_TYPES = {"id": int, "title": str, "author_id": int,
                  "author": str, "year": int}


class DatasetTests(unittest.TestCase):
    def test_schema_and_types(self):
        for book in BOOKS:
            self.assertEqual(set(book.keys()), EXPECTED_KEYS, book)
            for key, typ in EXPECTED_TYPES.items():
                self.assertIs(type(book[key]), typ, (book, key))

    def test_at_least_three_books(self):
        self.assertGreaterEqual(len(BOOKS), 3)

    def test_shared_author_id(self):
        counts = Counter(b["author_id"] for b in BOOKS)
        self.assertTrue(any(c >= 2 for c in counts.values()))

    def test_unique_ids(self):
        ids = [b["id"] for b in BOOKS]
        self.assertEqual(len(ids), len(set(ids)))

    def test_package_reexports(self):
        self.assertIs(PKG_BOOKS, BOOKS)
        self.assertIs(PkgBookStore, BookStore)


class BookStoreTests(unittest.TestCase):
    def setUp(self):
        self.store = BookStore()

    def test_list_books_returns_all(self):
        self.assertEqual(self.store.list_books(), BOOKS)

    def test_get_book_hit(self):
        book = self.store.get_book(1)
        self.assertIsNotNone(book)
        self.assertEqual(book["id"], 1)
        self.assertEqual(book, BOOKS[0])

    def test_get_book_miss(self):
        self.assertIsNone(self.store.get_book(99999))

    def test_books_by_author_hit(self):
        self.assertEqual([b["id"] for b in self.store.books_by_author(1)], [1, 2])

    def test_books_by_author_miss(self):
        self.assertEqual(self.store.books_by_author(999), [])

    def test_mutating_list_result_does_not_change_store(self):
        books = self.store.list_books()
        books[0]["title"] = "changed"
        books.append({"id": 100})
        self.assertEqual(self.store.list_books(), BOOKS)

    def test_mutating_get_result_does_not_change_store(self):
        book = self.store.get_book(1)
        book["title"] = "changed"
        self.assertEqual(self.store.get_book(1)["title"], "Pride and Prejudice")

    def test_mutating_filter_result_does_not_change_store(self):
        books = self.store.books_by_author(2)
        books[0]["author"] = "changed"
        self.assertEqual(self.store.books_by_author(2)[0]["author"],
                         "George Orwell")

    def test_store_isolated_from_source_dataset(self):
        source = [{"id": 1, "title": "T", "author_id": 1, "author": "A",
                   "year": 2000}]
        store = BookStore(source)
        source[0]["title"] = "changed"
        self.assertEqual(store.get_book(1)["title"], "T")

    def test_custom_dataset(self):
        custom = [
            {"id": 10, "title": "X", "author_id": 7, "author": "Ann", "year": 2001},
            {"id": 11, "title": "Y", "author_id": 7, "author": "Ann", "year": 2002},
        ]
        store = BookStore(custom)
        self.assertEqual(store.list_books(), custom)
        self.assertEqual(store.get_book(10)["title"], "X")
        self.assertIsNone(store.get_book(1))
        self.assertEqual([b["id"] for b in store.books_by_author(7)], [10, 11])
        self.assertEqual(store.books_by_author(1), [])

    def test_empty_custom_dataset(self):
        store = BookStore([])
        self.assertEqual(store.list_books(), [])
        self.assertIsNone(store.get_book(1))


if __name__ == "__main__":
    unittest.main()

